function Community() {
  return (
    <div style={{ padding: "15px" }}>
      <h3 style={{ color: "#4CAF50" }}>독서 모임</h3>

      <div style={box}>📖 한강 같이 읽기</div>
      <div style={box}>📚 자기계발 독서모임</div>
      <div style={box}>🧠 AI 독서 토론</div>
    </div>
  );
}

const box = {
  background: "white",
  padding: "15px",
  marginBottom: "10px",
  borderRadius: "12px"
};

export default Community;
